// decodeJSON decodes the members of an object whose opening brace has
// been read. path is the object's dotted path.
func (s *deviceShadow) decodeJSON(dec *jsontext.Decoder, path string) error {
	for {
		tok, err := dec.ReadToken()
		if err != nil {
			return err
		}
		if tok.Kind() == jsontext.KindEndObject {
			return nil
		}
		switch key := tok.String(); key {
		case "roots":
			if dec.PeekKind() == jsontext.KindNull {
				if _, err := dec.ReadToken(); err != nil {
					return err
				}
			} else {
				open, err := dec.ReadToken()
				if err != nil {
					return err
				}
				if open.Kind() != jsontext.KindBeginArray {
					return configJSONError(path+".roots", open, fmt.Errorf("expected an array, got %v", open.Kind()))
				}
				out := []string{}
				for dec.PeekKind() != jsontext.KindEndArray {
					v, err := dec.ReadToken()
					if err != nil {
						return err
					}
					if v.Kind() != jsontext.KindString {
						return configJSONError(path+".roots"+"["+strconv.Itoa(len(out))+"]", v, fmt.Errorf("expected a string, got %v", v.Kind()))
					}
					el := v.String()
					out = append(out, el)
				}
				if _, err := dec.ReadToken(); err != nil {
					return err
				}
				s.Roots = &out
			}
		case "tmp-dir":
			v, err := dec.ReadToken()
			if err != nil {
				return err
			}
			switch v.Kind() {
			case jsontext.KindNull:
			case jsontext.KindString:
				str := v.String()
				s.TempDir = &str
			default:
				return configJSONError(path+".tmp-dir", v, fmt.Errorf("expected a string, got %v", v.Kind()))
			}
		case "shell":
			v, err := dec.ReadToken()
			if err != nil {
				return err
			}
			switch v.Kind() {
			case jsontext.KindNull:
			case jsontext.KindString:
				str := v.String()
				s.Shell = &str
			default:
				return configJSONError(path+".shell", v, fmt.Errorf("expected a string, got %v", v.Kind()))
			}
		case "resume-buffer":
			v, err := dec.ReadToken()
			if err != nil {
				return err
			}
			switch v.Kind() {
			case jsontext.KindNull:
			case jsontext.KindNumber:
				raw, err := v.Int()
				if err != nil {
					return configJSONError(path+".resume-buffer", v, err)
				}
				if raw < math.MinInt || raw > math.MaxInt {
					return configJSONError(path+".resume-buffer", v, fmt.Errorf("%d overflows int", raw))
				}
				num := int(raw)
				s.ResumeBuffer = &num
			default:
				return configJSONError(path+".resume-buffer", v, fmt.Errorf("expected a number, got %v", v.Kind()))
			}
		case "max-grace":
			v, err := dec.ReadToken()
			if err != nil {
				return err
			}
			switch v.Kind() {
			case jsontext.KindNull:
			case jsontext.KindString:
				var slot impl.Duration
				if err := slot.UnmarshalText([]byte(v.String())); err != nil {
					return configJSONError(path+".max-grace", v, err)
				}
				s.MaxGrace = &slot
			default:
				return configJSONError(path+".max-grace", v, fmt.Errorf("expected a text scalar (e.g. \"30s\"), got %v", v.Kind()))
			}
		default:
			if reject, _ := json.GetOption(dec.Options(), json.RejectUnknownMembers); reject {
				return &configulator.UnknownKeyError{Path: path + "." + configQuoteKey(key)}
			}
			if err := dec.SkipValue(); err != nil {
				return err
			}
		}
	}
}

